#include <iostream>
#include <string>

struct Address { std::string city; int postal_code; };
struct Person { std::string name; Address address; };
int main() {
    const Person person{"Mira", {"Ahmedabad", 380001}};
    std::cout << person.name << " lives in " << person.address.city << '\n';
}
